    def open_data_tran(self):
        options = QFileDialog.Options()
        path = QFileDialog.getExistingDirectory(None, "Select Directory", options=options)
        if path:
            process_path(path)
            last_foler_name = os.path.basename(path)
            edf_path = os.path.join(path,f"{last_foler_name}.edf")
            self.showInfo(edf_path)

            base_path = os.path.dirname(edf_path)
            result_path = os.path.join(base_path,'Result')
            from datetime import datetime
            folder_name = datetime.now().strftime('%Y%m%d_%H%M%S')
            folder_path = os.path.join(result_path,folder_name)
            os.makedirs(result_path,exist_ok=True)
            os.makedirs(folder_path,exist_ok=True)
            self.updateDescription(folder_path)

    # edf/bdf文件路径
    def open_data_import(self):
        self.browse_files()

    def browse_files(self):
        options = QFileDialog.Options()
        file_filter = 'EDF and BDF Files (*.edf *.bdf)'
        file_name, _ = QFileDialog.getOpenFileName(None,"Select EDF or BDF File",options=options,filter=file_filter)
        if file_name:
            self.file_path = file_name
            self.process_path()

    def process_path(self):
        if self.file_path.endswith('.edf') or self.file_path.endswith('.bdf'):
            self.showInfo(self.file_path)

            base_path = os.path.dirname(self.file_path)
            result_path = os.path.join(base_path,'Result')
            from datetime import datetime
            folder_name = datetime.now().strftime('%Y%m%d_%H%M%S')
            folder_path = os.path.join(result_path,folder_name)
            os.makedirs(result_path,exist_ok=True)
            os.makedirs(folder_path,exist_ok=True)
            self.updateDescription(folder_path)
        else:
            QMessageBox.critical(None, "File Error", "The selected file is not a .edf file. Please select a valid .edf file.")

