    def showInfo(self, file_path):
        try:
            file_extension = os.path.splitext(file_path)[1].lower()
            edf_r = EdfReader(file_path)
            start_time = edf_r.getStartdatetime()
            del edf_r

            if file_extension == '.edf':
                self.raw = mne.io.read_raw_edf(file_path, preload=True, verbose=False)
                # self.raw._data = self.raw.get_data().astype('float32') # 将数据转换为float32类型

            elif file_extension == '.bdf':
                self.raw = mne.io.read_raw_bdf(file_path, preload=True, verbose=False)
            
            self.raw.info['description'] = file_path
            # data_in_v = self.raw.get_data()
            # data_in_uv = data_in_v * 1e6
            
            # info = self.raw.info
            # # 注意
            # self.raw_processed = mne.io.RawArray(data_in_uv,info)

            # 直接将数据转换为微伏（而不是先存储在中间变量中）
            self.raw._data *= 1e6  # 将数据转换为微伏，直接修改self.raw._data

            # 如果你只想保留最终处理后的数据，创建一个新的 RawArray 对象
            self.raw_processed = mne.io.RawArray(self.raw._data, self.raw.info)

            # 删除不再需要的原始数据
            del self.raw

            print(self.raw_processed.info['description'])
            self.info_text = f"Raw Object:\n{self.raw_processed}\n\nRaw Info:\n{self.raw_processed.info}"
            self.textEdit.setText(self.info_text)

            # 成功加载数据后启用菜单和关闭
            self.menuPreprocess.setEnabled(True)
            self.menuAnalysis_module.setEnabled(True)
            self.action_close_file.setEnabled(True)

        except Exception as e:
            self.textEdit.setText(f"Failed to load the file: {e}")
            # 加载失败时确保菜单保持禁用
            self.menuPreprocess.setEnabled(False)
            self.menuAnalysis_module.setEnabled(False)
            raise e

    def updateDescription(self, folder_path):
        self.raw_processed.info['description'] = folder_path

    def updateRawObject(self, raw=None, reject_log=None):
        """更新Raw对象和显示信息"""
        self.raw_processed = raw
        
        # 准备显示文本
        if raw is None:
            info_text = "Raw Object: None\n"
            if reject_log:
                info_text += reject_log
            else:
                info_text += "\nAll data has been rejected."
        else:
            info_text = f"Raw Object:\n{self.raw_processed}\n\nRaw Info:\n{self.raw_processed.info}"
            if reject_log:
                info_text += reject_log
        
        # 更新显示
        self.textEdit.setText(info_text)
        print("Updated text:", info_text)  # 调试信息
        
        # 更新菜单状态
        has_data = raw is not None
        self.menuPreprocess.setEnabled(has_data)
        self.menuAnalysis_module.setEnabled(has_data)
        self.action_close_file.setEnabled(has_data)

