    def open_qlass_analysis(self):
        if self.raw_processed is None:
            QtWidgets.QMessageBox.warning(None, "Error", "Please load data file first.")
            return
            
        try:
            # 如果已经存在窗口，先关闭它
            if self.qlass_window is not None:
                self.close_qlass_analysis()

            from .QlassAnalysis import Ui_qlass_analysis
            self.qlass_window = QtWidgets.QWidget()
            self.qlass_ui = Ui_qlass_analysis()
            self.qlass_ui.setupUi(self.qlass_window)
            self.qlass_ui.import_raw(self.raw_processed)
            
            # 连接窗口关闭信号 - 使用正确的方法绑定
            self.qlass_window.closeEvent = self.create_close_handler()
            
            self.qlass_window.show()
            
        except Exception as e:
            print(f"Error opening Qlass Analysis window: {str(e)}")

    def create_close_handler(self):
        """创建一个闭包来处理关闭事件"""
        def handle_close(event):
            print("Qlass Analysis window closing...")  # 调试信息
            self.close_qlass_analysis(event)
        return handle_close

    def close_qlass_analysis(self, event=None):
        """关闭睡眠分析窗口并清理所有相关资源"""
        try:
            print("Starting Qlass Analysis cleanup...")

            if self.qlass_ui is not None:
                # 先处理线程
                if hasattr(self.qlass_ui, 'thread_run'):
                    thread = self.qlass_ui.thread_run
                    if thread.isRunning():
                        thread.terminate()
                        thread.wait()
                    thread.cleanup()  # 调用新的cleanup方法
                    thread.deleteLater()  # 确保线程被正确删除

                # 清理matplotlib资源
                if hasattr(self.qlass_ui, 'figure'):
                    plt.close(self.qlass_ui.figure)
                    self.qlass_ui.figure.clear()
                    del self.qlass_ui.figure

                if hasattr(self.qlass_ui, 'canvas'):
                    self.qlass_ui.canvas.close()
                    del self.qlass_ui.canvas

                # 清理所有大型数据属性
                large_data_attrs = [
                    'raw_processed', 'df_score', 'eeg_data', 'emg_data',
                    'acc_data', 'spectrogram_data', 'scores', 'stages',
                    'color_epochs', 'highlight_lines', 'epochlabels'
                ]
                
                for attr in large_data_attrs:
                    if hasattr(self.qlass_ui, attr):
                        delattr(self.qlass_ui, attr)

                # 断开所有信号连接
                try:
                    self.qlass_ui.thread_run.signal.disconnect()
                except:
                    pass

                # 删除UI对象
                self.qlass_ui.deleteLater()
                self.qlass_ui = None

            # 关闭并删除窗口
            if self.qlass_window is not None:
                self.qlass_window.close()
                self.qlass_window.deleteLater()
                self.qlass_window = None

            # 强制多次垃圾回收
            import gc
            gc.collect()
            gc.collect()

            # 打印内存使用情况
            import psutil
            process = psutil.Process()
            print(f"Memory usage after closing Qlass Analysis: {process.memory_info().rss / 1024 / 1024:.2f} MB")

        except Exception as e:
            print(f"Error during Qlass Analysis cleanup: {str(e)}")
            import traceback
            traceback.print_exc()
        finally:
            if event:
                event.accept()

    def close_file(self):
        """关闭文件时清理所有打开的窗口和数据"""
        try:
            # 1. 关闭所有特殊窗口
            special_windows = [
                (self.qlass_window, self.close_qlass_analysis),
                (getattr(self, 'filter_window', None), None),
                (getattr(self, 'select_window', None), None),
                (getattr(self, 'reject_window', None), None),
                (getattr(self, 'basical_window', None), None),
                (getattr(self, 'EMG_window', None), None),
                (getattr(self, 'ECG_window', None), None),
                (getattr(self, 'epilepsy_window', None), None)
            ]

            for window, close_func in special_windows:
                if window is not None:
                    if close_func:
                        close_func()
                    else:
                        window.close()
                        # 获取窗口的属性名并安全地删除
                        window_name = window.objectName()
                        if window_name and hasattr(self, window_name):
                            delattr(self, window_name)

            # 2. 清理UI对象
            ui_attributes = [
                'qlass_ui', 'filter_ui', 'select_ui', 'reject_ui', 
                'basical_ui', 'EMG_ui', 'ECG_ui', 'epilepsy_ui'
            ]
            
            for attr in ui_attributes:
                if hasattr(self, attr):
                    ui_obj = getattr(self, attr)
                    if hasattr(ui_obj, 'closeEvent'):
                        ui_obj.closeEvent(QtCore.QEvent(QtCore.QEvent.Close))
                    if hasattr(ui_obj, 'raw_processed'):
                        del ui_obj.raw_processed
                    delattr(self, attr)

            # 3. 清理数据对象
            data_objects = ['raw', 'raw_processed', 'file_path', 'info_text', 'info_text2']
            for obj in data_objects:
                if hasattr(self, obj):
                    delattr(self, obj)

            # 4. 重置UI状态
            self.textEdit.clear()
            self.menuPreprocess.setEnabled(False)
            self.menuAnalysis_module.setEnabled(False)
            self.action_close_file.setEnabled(False)
            self.statusbar.showMessage("File closed and memory cleared", 2000)

            # 5. 强制垃圾回收
            import gc
            gc.collect()
            gc.collect()

            # 6. 打印内存使用情况（调试用）
            import psutil
            process = psutil.Process()
            print(f"Memory usage after cleanup: {process.memory_info().rss / 1024 / 1024:.2f} MB")

        except Exception as e:
            print(f"Error during cleanup: {str(e)}")
            import traceback
            traceback.print_exc()

    def exit_application(self):
        """退出应用程序"""
        reply = QtWidgets.QMessageBox.question(
            None,
            'Exit',
            'Are you sure you want to exit?',
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
            QtWidgets.QMessageBox.No
        )
        
        if reply == QtWidgets.QMessageBox.Yes:
            # 确保关闭睡眠分期窗口
            if self.qlass_window is not None:
                self.close_qlass_analysis()
            
            # 关闭所有窗口
            for window, ui in self.windows:
                window.close()
            
            # 清理资源
            self.windows.clear()
            if hasattr(self, 'raw'):
                del self.raw
            if hasattr(self, 'raw_processed'):
                del self.raw_processed
            
            # 强制垃圾回收
            import gc
            gc.collect()
            
            QtWidgets.QApplication.quit()

