    def open_epilepsy_analysis(self):
        if self.raw_processed is None:
            QtWidgets.QMessageBox.warning(None, "Error", "Please load data file first.")
            return
        # from .EpilepsyAnalysis import Ui_epilepsy_analysis  # 更新导入
        from AR_analyser_PC.src.EpilepsyAnalysis_ML import Ui_epilepsy_analysis
        self.epilepsy_window = QtWidgets.QWidget()
        self.epilepsy_ui = Ui_epilepsy_analysis()
        self.epilepsy_ui.setupUi(self.epilepsy_window)
        self.epilepsy_ui.import_raw(self.raw_processed)
        self.epilepsy_window.show()

